<script setup lang="ts">
import { getMessageText } from '@/01-models/message-text';
import { computed, ref, onUnmounted, watch } from 'vue';
import { XIcon, HistoryIcon, ClockIcon, CpuIcon, ArrowDownIcon, CopyIcon, CheckIcon, ArrowRightIcon, RotateCcwIcon, EyeIcon, EyeOffIcon } from 'lucide-vue-next';
import { idToRaw } from '@/01-models/ids';
import type { MessageId } from '@/01-models/ids';
import type { MessageNode } from '@/01-models/types';
import { computeWordDiff, type DiffPart } from '@/utils/diff';
import { lazyStrings } from '@/strings';

const props = defineProps<{
  isOpen: boolean,
  siblings: MessageNode[],
  currentMessageId: MessageId,
}>();

const emit = defineEmits<{
  (e: 'close'): void,
}>();

type DiffVisibility = 'visible' | 'hidden';
const diffVisibility = ref<DiffVisibility>('visible');

const baseVersionId = ref<MessageId | undefined>(undefined);
const targetVersionId = ref<MessageId | undefined>(undefined);
const skippedMessageIds = ref<Set<MessageId>>(new Set());
const visibleCount = ref(10);
const loadMoreTrigger = ref<HTMLElement | null>(null);

let observer: IntersectionObserver | undefined;

function setupObserver() {
  if (typeof IntersectionObserver === 'undefined') return;
  if (observer) observer.disconnect();

  observer = new IntersectionObserver((entries) => {
    const entry = entries[0];
    if (entry?.isIntersecting) {
      if (visibleCount.value < props.siblings.length) {
        visibleCount.value += 10;
      }
    }
  }, { threshold: 0.1 });

  if (loadMoreTrigger.value) {
    observer.observe(loadMoreTrigger.value);
  }
}

watch([() => props.isOpen, loadMoreTrigger], ([isOpen, trigger]) => {
  if (isOpen && trigger) {
    setupObserver();
  } else if (!isOpen && observer) {
    observer.disconnect();
    observer = undefined;
    visibleCount.value = 10; // Reset when closed
  }
});

onUnmounted(() => {
  if (observer) observer.disconnect();
});

interface VersionItem {
  id: MessageId,
  versionNumber: number,
  content: string,
  modelId: string | undefined,
  timestamp: number,
}

const versionItems = computed((): VersionItem[] => {
  return props.siblings.map((msg, i) => ({
    id: msg.id,
    versionNumber: i + 1,
    content: getMessageText({ message: msg }),
    modelId: msg.modelId,
    timestamp: msg.createdAt,
  }));
});

const customDiff = computed(() => {
  if (!baseVersionId.value || !targetVersionId.value) return null;
  const base = versionItems.value.find(v => v.id === baseVersionId.value);
  const target = versionItems.value.find(v => v.id === targetVersionId.value);
  if (!base || !target) return null;

  return {
    base,
    target,
    parts: computeWordDiff({ oldText: base.content, newText: target.content }),
  };
});

interface SequentialDiff {
  id: MessageId,
  versionNumber: number,
  timestamp: number,
  modelId: string | undefined,
  content: string,
  diffParts: DiffPart[],
  isCurrent: boolean,
  isSkipped: boolean,
}

const copiedId = ref<MessageId | undefined>(undefined);

const sequentialDiffs = computed(() => {
  const result: SequentialDiff[] = [];
  const reversedSiblings = [...props.siblings].reverse();

  for (let i = 0; i < reversedSiblings.length; i++) {
    const msg = reversedSiblings[i];
    if (!msg) continue;

    const isSkipped = skippedMessageIds.value.has(msg.id);

    let diffParts: DiffPart[] = [];

    // Only calculate diff if within visibleCount and not skipped
    if (i < visibleCount.value && !isSkipped) {
      const originalIndex = props.siblings.findIndex(m => m.id === msg.id);

      // Find previous non-skipped message in chronological order
      let prevMsg: MessageNode | undefined = undefined;
      for (let j = originalIndex - 1; j >= 0; j--) {
        const potentialPrev = props.siblings[j];
        if (potentialPrev && !skippedMessageIds.value.has(potentialPrev.id)) {
          prevMsg = potentialPrev;
          break;
        }
      }

      diffParts = prevMsg
        ? computeWordDiff({ oldText: getMessageText({ message: prevMsg }), newText: getMessageText({ message: msg }) })
        : [{ type: 'unchanged', value: getMessageText({ message: msg }) } as DiffPart];
    }

    result.push({
      id: msg.id,
      versionNumber: props.siblings.findIndex(m => m.id === msg.id) + 1,
      timestamp: msg.createdAt,
      modelId: msg.modelId,
      content: getMessageText({ message: msg }),
      diffParts,
      isCurrent: msg.id === props.currentMessageId,
      isSkipped,
    });
  }

  return result;
});

function toggleSkip({ id }: { id: MessageId }) {
  const next = new Set(skippedMessageIds.value);
  if (next.has(id)) {
    next.delete(id);
  } else {
    next.add(id);
    // If it was base or target, clear it
    if (baseVersionId.value === id) baseVersionId.value = undefined;
    if (targetVersionId.value === id) targetVersionId.value = undefined;
  }
  skippedMessageIds.value = next;
}

async function handleCopy({ id, content }: { id: MessageId, content: string }) {
  try {
    await navigator.clipboard.writeText(content);
    copiedId.value = id;
    setTimeout(() => {
      if (copiedId.value === id) copiedId.value = undefined;
    }, 2000);
  } catch (err) {
    console.error('Failed to copy version content:', err);
  }
}

function formatDate({ timestamp }: { timestamp: number }): string {
  return new Date(timestamp).toLocaleString();
}

function handleClose() {
  emit('close');
}

function clearSelection() {
  baseVersionId.value = undefined;
  targetVersionId.value = undefined;
}

defineExpose({
  ...((__BUILD_MODE_IS_TEST__ && {
    TEST_ONLY: {},
  }) || {}),
});

